// Constant members, a function table and a namespace function read through
// receivers with side effects: each receiver still runs.
var ns = ns || {};
// Reads that run before their members are created: Node throws.
var early = (function () {
  var out = [];
  try {
    out.push(ns.Late.X);
  } catch (e) {
    out.push(e.constructor.name);
  }
  try {
    out.push(ns.later());
  } catch (e) {
    out.push(e.constructor.name);
  }
  return out.join(" ");
})();
ns.Late = { X: 5 };
ns.later = function () {
  return "later";
};
ns.early = function () {
  return early + " " + ns.Late.X + " " + ns.later();
};
ns.Kind = { A: 1, B: 2 };
ns.ops = {
  add: function (a, b) {
    return a + b;
  },
  sub: function (a, b) {
    return a - b;
  },
};
ns.util = {
  twice: function (x) {
    return 2 * x;
  },
};
var reads = 0;
ns.run = function (op) {
  return (reads++, ns.Kind).A + (reads++, ns.ops)[op](5, 2) + (reads++, ns.util).twice(3);
};
ns.reads = function () {
  return reads;
};
// `__proto__: null` in a literal sets the prototype: no own property.
ns.Proto = { __proto__: null, A: 1 };
ns.proto = function () {
  return String(ns.Proto.__proto__) + " " + ns.Proto.A;
};
module.exports = { ns: ns };
